import 'reflect-metadata';
import {writeFileSync} from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import { DataSource, EntitySchema, getMetadataArgsStorage } from 'typeorm';
import { JwtService } from '@nestjs/jwt';
import { caching } from 'cache-manager';
import { redisStore } from 'cache-manager-redis-yet';
import express from 'express';
import request from 'supertest';
import * as jwt from 'jsonwebtoken';

import { UserSessionService } from 'src/engine/core-modules/user-session/services/user-session.service';
import { UserSessionCookieService } from 'src/engine/core-modules/user-session/services/user-session-cookie.service';
import { UserSessionEntity } from 'src/engine/core-modules/user-session/user-session.entity';
import { AppTokenEntity, AppTokenType } from 'src/engine/core-modules/app-token/app-token.entity';
import { UserEntity } from 'src/engine/core-modules/user/user.entity';
import { WorkspaceEntity } from 'src/engine/core-modules/workspace/workspace.entity';
