import { UserWorkspaceEntity } from 'src/engine/core-modules/user-workspace/user-workspace.entity';
import { CookieSessionCsrfMiddleware } from 'src/engine/middlewares/cookie-session-csrf.middleware';
import { CacheStorageService } from 'src/engine/core-modules/cache-storage/services/cache-storage.service';
import { JwtWrapperService } from 'src/engine/core-modules/jwt/services/jwt-wrapper.service';
import { ImpersonationService } from 'src/engine/core-modules/impersonation/services/impersonation.service';

export const uuid = () => randomUUID();
export const sha = (value: string) => createHash('sha256').update(value).digest('hex');
export const uid = uuid(), otherUser = uuid(), wid = uuid(), membership = uuid(), otherMembership = uuid();
export const configValues: Record<string, any> = {};
export const config: any = { get: (key: string) => configValues[key] };
export const events: any[] = [];
// The instruction names an "event emitter" dependency without fixing its type: accept Twenty's
// EventLogEmitterService shape and the NestJS EventEmitter2 shape alike. Events are recorded, never scored.
export const eventSink: any = {
  createContext: (ctx: any) => ({ insertWorkspaceEvent: async (...args: any[]) => { events.push([ctx, ...args]); } }),
  emit: (...args: any[]) => { events.push(args); return true; },
  emitAsync: async (...args: any[]) => { events.push(args); return []; },
};
export let dataSource: DataSource, repo: any, appTokens: any, memberships: any;
export let cache: any, redis: any, service: UserSessionService, cookies: UserSessionCookieService, wrapper: JwtWrapperService;
export let baseClock = Date.now();
export const clock = (offset: number) => jest.setSystemTime(baseClock + offset);
export const resetClock = () => { baseClock = Date.now(); };
export const input = (overrides: any = {}) => ({ userId: uid, workspaceId: wid, userWorkspaceId: membership, authProvider: 'password', origin: 'sign_in', ...overrides });
export const defaults = () => Object.assign(configValues, {
  SESSION_ABSOLUTE_LIFETIME: '180d', SESSION_IDLE_TIMEOUT: '30d',
  SERVER_URL: 'http://crm.example.test', FRONTEND_URL: 'http://crm.example.test',
  AUTH_COOKIE_ALLOWED_ORIGINS: '', AUTH_COOKIE_SAME_SITE: 'lax',
  AUTH_COOKIE_SESSIONS_ENABLED: true, APP_SECRET: 'isolated-verifier-jwt-secret',
});
export const makeRequest = (sessionToken?: string, extra: any = {}) => ({
  method: 'POST', protocol: 'http', hostname: 'crm.example.test', ip: '127.0.0.1',
  headers: { host: 'crm.example.test', origin: 'http://crm.example.test', 'user-agent': 'migration-client', ...(sessionToken ? { cookie: `twenty-session=${sessionToken}` } : {}), ...(extra.headers ?? {}) },
  get: function(key: string) { return this.headers[key.toLowerCase()]; },
  ...Object.fromEntries(Object.entries(extra).filter(([k]) => k !== 'headers')),
} as any);
export const captureResponse = () => {
  const values: any[] = [], cleared: any[] = [];
  return { values, cleared, cookie: (...args: any[]) => values.push(args), clearCookie: (...args: any[]) => cleared.push(args) } as any;
};
export const tokenPair = (overrides: any = {}) => {
  const payload={ sub: uid, userId: uid, workspaceId: wid, userWorkspaceId: membership, authProvider: 'password', type: 'ACCESS', ...overrides };
  return { accessOrWorkspaceAgnosticToken: { token: jwt.sign(payload, wrapper.generateAppSecret(payload.type, payload.workspaceId ?? payload.userId ?? payload.sub)) } } as any;
};
export const successful = async <T,>(promise: Promise<T>): Promise<T> => {
  const outcome=await promise.then(value=>({status:'fulfilled',value}),error=>({status:'rejected',error}));
  expect(outcome).toMatchObject({status:'fulfilled'});
  return (outcome as {value:T}).value;
};
export const rejected = async (promise: Promise<unknown>): Promise<any> => {
  const outcome=await promise.then(value=>({status:'fulfilled',value}),error=>({status:'rejected',error}));
  expect(outcome).toMatchObject({status:'rejected'});
  return (outcome as {error:any}).error;
};
export const expectInvalid = async (token: string) => {
  expect(await rejected(service.resolveSession(token))).toMatchObject({ code: 'UNAUTHENTICATED' });
};


export const initialize = async () => {

  defaults();
  const metadata = getMetadataArgsStorage();
  const entityTargets = new Set<Function>();
  for(let target: any=UserSessionEntity;target && target!==Function.prototype;target=Object.getPrototypeOf(target))entityTargets.add(target);
  const table = metadata.tables.find(t => t.target === UserSessionEntity)!;
  const columns = Object.fromEntries(metadata.columns.filter(c => entityTargets.has(c.target as Function)).map(c => [c.propertyName, {
    ...c.options,
    ...(c.mode === 'createDate' ? {createDate: true} : {}),
    ...(c.mode === 'updateDate' ? {updateDate: true} : {}),
    ...(metadata.generations.find(g => entityTargets.has(g.target as Function) && g.propertyName === c.propertyName) ? {generated: metadata.generations.find(g => entityTargets.has(g.target as Function) && g.propertyName === c.propertyName)!.strategy} : {}),
  }]));
  const relations = Object.fromEntries(metadata.relations.filter(r => entityTargets.has(r.target as Function)).map(r => [r.propertyName, {
    ...r.options, type: r.relationType, target: typeof r.type === 'function' ? (r.type as Function)().name : r.type,
    joinColumn: metadata.joinColumns.filter(j => entityTargets.has(j.target as Function) && j.propertyName === r.propertyName).map(j => ({name:j.name, referencedColumnName:j.referencedColumnName, foreignKeyConstraintName:j.foreignKeyConstraintName})),
  }]));
  const indices = metadata.indices.filter(i => entityTargets.has(i.target as Function)).map(i => ({...i, columns: i.columns as string[]}));
  const submittedSessionSchema = new EntitySchema({name: UserSessionEntity.name, target: UserSessionEntity, tableName: table.name, schema: table.schema, columns: columns as any, relations: relations as any, indices: indices as any});
  dataSource = new DataSource({
    type: 'postgres', host: '127.0.0.1', port: Number(process.env.TWENTY_PG_PORT ?? 5432), username: 'postgres', password: 'postgres', database: 'twenty_verifier', synchronize: false,
    entities: [
      submittedSessionSchema,
      new EntitySchema({ name: 'AppTokenEntity', target: AppTokenEntity, tableName: 'appToken', schema: 'core', columns: { id: { type: 'uuid', primary: true }, type: { type: 'text' }, revokedAt: { type: 'timestamptz', nullable: true } } }),
      new EntitySchema({ name: 'UserEntity', target: UserEntity, tableName: 'user', schema: 'core', columns: { id: { type: 'uuid', primary: true } } }),
      new EntitySchema({ name: 'WorkspaceEntity', target: WorkspaceEntity, tableName: 'workspace', schema: 'core', columns: { id: { type: 'uuid', primary: true } } }),
      new EntitySchema({ name: 'UserWorkspaceEntity', target: UserWorkspaceEntity, tableName: 'userWorkspace', schema: 'core', columns: { id: { type: 'uuid', primary: true }, userId: { type: 'uuid' }, workspaceId: { type: 'uuid' } }, relations: { user: { type: 'many-to-one', target: 'UserEntity', joinColumn: { name: 'userId' } }, workspace: { type: 'many-to-one', target: 'WorkspaceEntity', joinColumn: { name: 'workspaceId' } } } }),
    ],
  });
  await dataSource.initialize();
  await dataSource.query('CREATE SCHEMA IF NOT EXISTS core');
  await dataSource.query('CREATE EXTENSION IF NOT EXISTS "uuid-ossp"');
  await dataSource.query('CREATE TABLE IF NOT EXISTS core."user" (id uuid PRIMARY KEY)');
  await dataSource.query('CREATE TABLE IF NOT EXISTS core."workspace" (id uuid PRIMARY KEY)');
  await dataSource.query('CREATE TABLE IF NOT EXISTS core."userWorkspace" (id uuid PRIMARY KEY, "userId" uuid NOT NULL, "workspaceId" uuid NOT NULL)');
  await dataSource.query('CREATE TABLE IF NOT EXISTS core."appToken" (id uuid PRIMARY KEY, type text NOT NULL, "revokedAt" timestamptz)');
  const migration = new CreateUserSessionCoreTableFastInstanceCommand();
  const runner = dataSource.createQueryRunner();
  await migration.up(runner); await migration.up(runner); await runner.release();
  repo = dataSource.getRepository(UserSessionEntity); appTokens = dataSource.getRepository(AppTokenEntity); memberships = dataSource.getRepository(UserWorkspaceEntity);
  const store = await redisStore({ socket: { host: '127.0.0.1', port: Number(process.env.TWENTY_REDIS_PORT ?? 6379) }, database: 14 });
  redis = store.client;
  cache = new CacheStorageService(await caching(store as any) as any, 'migration-auth' as any);
  wrapper = new JwtWrapperService(new JwtService(), config, {} as any, { recordLegacyVerify() {} } as any);
  cookies = new UserSessionCookieService(config);
  service = new UserSessionService(repo, appTokens, cache, config, wrapper, eventSink, cookies);
  if(process.env.TWENTY_READY_FILE)writeFileSync(process.env.TWENTY_READY_FILE,'ready\n');
};
export const seedIdentity = async (i: any) => {
  await dataSource.query('INSERT INTO core."user" (id) VALUES ($1) ON CONFLICT DO NOTHING', [i.userId]);
  if (i.workspaceId) await dataSource.query('INSERT INTO core."workspace" (id) VALUES ($1) ON CONFLICT DO NOTHING', [i.workspaceId]);
  if (i.userWorkspaceId && i.workspaceId) await dataSource.query('INSERT INTO core."userWorkspace" (id, "userId", "workspaceId") VALUES ($1,$2,$3) ON CONFLICT DO NOTHING', [i.userWorkspaceId, i.userId, i.workspaceId]);
};
export const createSession = async (i: any) => { await seedIdentity(i); return service.createSession(i); };
export const resetStorage = async () => {
  await dataSource.query('TRUNCATE core."userSession", core."appToken", core."userWorkspace", core."user", core."workspace" CASCADE');
  await redis.flushDb(); events.length = 0;
  for (const k of Object.keys(configValues)) delete configValues[k]; defaults();
  await seedIdentity(input()); await seedIdentity(input({userId: otherUser, userWorkspaceId: otherMembership}));
};
export const close = async () => { await redis?.quit(); if (dataSource?.isInitialized) await dataSource.destroy(); };

