test('C01 opaque persisted sessions and scope', async () => {
  const issued = await Promise.all(Array.from({ length: 12 }, () => createSession(input())));
  expect(new Set(issued.map(x => x.sessionToken)).size).toBe(12);
  for (const { sessionToken, session } of issued) {
    expect(sessionToken).toMatch(/^sess_[A-Za-z0-9_-]{32,}$/);
    const persisted = await repo.findOneByOrFail({ id: session.id });
    expect(persisted.tokenHash).toBe(sha(sessionToken));
    expect(JSON.stringify(persisted)).not.toContain(sessionToken);
    expect((await successful(service.resolveSession(sessionToken))).payload).toMatchObject({ type: 'ACCESS', userId: uid, workspaceId: wid, userWorkspaceId: membership, authProvider: 'password' });
  }
  const agnostic = await successful(createSession(input({ workspaceId: undefined, userWorkspaceId: undefined })));
  expect((await successful(service.resolveSession(agnostic.sessionToken))).payload).toMatchObject({ type: 'WORKSPACE_AGNOSTIC', userId: uid });
  expect(await rejected(createSession(input({ userWorkspaceId: undefined })))).toBeDefined();
  expect(await rejected(createSession(input({ workspaceId: undefined })))).toBeDefined();
