  expect(res.values).toHaveLength(1);
  const original = res.values[0][1]; expect(await repo.count()).toBe(1);
  for (let i = 0; i < 3; i++) {
    const next = captureResponse();
    await successful(service.issueSessionForTokenPair({ tokenPair: tokenPair(), request: makeRequest(original, { res: next }), origin: 'renewal_bridge' }));
    expect(next.values).toHaveLength(0);
  }
  expect(await repo.count()).toBe(1);
  const replacement = captureResponse();
  await successful(service.issueSessionForTokenPair({ tokenPair: tokenPair(), request: makeRequest(original, { res: replacement }), origin: 'sign_in' }));
  expect(replacement.values).toHaveLength(1); expect(replacement.values[0][1]).not.toBe(original);
  await expectInvalid(original);
  const foreignScope = captureResponse();
  await successful(service.issueSessionForTokenPair({ tokenPair: tokenPair({ userId: otherUser, sub: otherUser, userWorkspaceId: otherMembership }), request: makeRequest(replacement.values[0][1], { res: foreignScope }), origin: 'renewal_bridge' }));
  expect(foreignScope.values).toHaveLength(1);
  expect((await successful(service.resolveSession(foreignScope.values[0][1]))).payload.userId).toBe(otherUser);
  await expectInvalid(replacement.values[0][1]);
  const survivor = await successful(createSession(input())), response = captureResponse(), legacyPair = tokenPair();
  const dependencies:any[]=Array.from({length:27},()=>({}));
  dependencies[5]={generateTokensFromRefreshToken:async()=>legacyPair};dependencies[25]=service;dependencies[26]=cookies;
  const resolver=new AuthResolver(...dependencies as ConstructorParameters<typeof AuthResolver>);
  const outage=jest.spyOn(cache,'get').mockRejectedValueOnce(new Error('injected Redis read outage'));
  const result=await successful(resolver.renewToken({appToken:'legacy-refresh'},{req:makeRequest(survivor.sessionToken,{res:response})}));
  outage.mockRestore();
  expect(result.tokens).toEqual(legacyPair);expect(response.cleared).toEqual([]);
  await successful(service.resolveSession(survivor.sessionToken));
});

test('C03 absolute and idle expiry across cache paths', async () => {
  for (const warm of [false, true]) {
    clock(0); configValues.SESSION_ABSOLUTE_LIFETIME = '40s'; configValues.SESSION_IDLE_TIMEOUT = '1d';
    const a = await successful(createSession(input())); if (warm) await successful(service.resolveSession(a.sessionToken));
    clock(40_000); await expectInvalid(a.sessionToken);
    clock(0); configValues.SESSION_ABSOLUTE_LIFETIME = '180d'; configValues.SESSION_IDLE_TIMEOUT = '40s';
    const b = await successful(createSession(input())); if (warm) await successful(service.resolveSession(b.sessionToken));
    clock(40_000); await expectInvalid(b.sessionToken);
  }
  const declared=new ConfigVariables();expect(declared.AUTH_COOKIE_SESSIONS_ENABLED).toBe(false);
  expect(ms(declared.SESSION_ABSOLUTE_LIFETIME as any)).toBe(180*86400000);expect(ms(declared.SESSION_IDLE_TIMEOUT as any)).toBe(30*86400000);
  clock(0);defaults();const ordinary=await successful(createSession(input()));
  expect(ordinary.session.expiresAt.getTime()).toBe(baseClock+180*86400000);
  clock(30*86400000);await expectInvalid(ordinary.sessionToken);
  clock(0);const impersonated=await successful(createSession(input({isImpersonating:true,impersonatorUserWorkspaceId:membership,impersonatedUserWorkspaceId:uuid()})));
  expect(impersonated.session.expiresAt.getTime()).toBe(baseClock+86400000);
  clock(86400000);await expectInvalid(impersonated.sessionToken);
  await repo.clear();await redis.flushDb();clock(0);defaults();
  const live=await successful(createSession(input())),revoked=await successful(createSession(input())),expired=await successful(createSession(input())),idle=await successful(createSession(input()));
  await successful(service.revokeSessionByToken(revoked.sessionToken,'USER_SIGN_OUT' as any));
  await repo.update(expired.session.id,{expiresAt:new Date(baseClock)});
  await repo.update(idle.session.id,{lastActiveAt:new Date(baseClock-30*86400000)});
  expect((await successful(service.findActiveSessionsForUser(uid))).map(x=>x.id)).toEqual([live.session.id]);
  expect(await successful(service.findActiveSessionsForUser(otherUser))).toEqual([]);
});

test('C04 short idle activity touch cannot revive revoked sessions', async () => {
  configValues.SESSION_IDLE_TIMEOUT = '40s';
  const active = await successful(createSession(input()));
  await dataSource.query('CREATE TABLE core."verifierActivityWrites" (n integer NOT NULL)');
  await dataSource.query('INSERT INTO core."verifierActivityWrites" VALUES (0)');
  await dataSource.query(`CREATE FUNCTION core.verifier_count_activity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE core."verifierActivityWrites" SET n=n+1; RETURN NEW; END $$`);
  await dataSource.query('CREATE TRIGGER verifier_activity AFTER UPDATE OF "lastActiveAt" ON core."userSession" FOR EACH ROW EXECUTE FUNCTION core.verifier_count_activity()');
  try {
    for(let i=0;i<30;i++){clock(i*10);await successful(service.resolveSession(active.sessionToken));}
    const [writes]=await dataSource.query('SELECT n FROM core."verifierActivityWrites"');expect(writes.n).toBeLessThanOrEqual(1);
  } finally {
    await dataSource.query('DROP TRIGGER verifier_activity ON core."userSession"');await dataSource.query('DROP FUNCTION core.verifier_count_activity()');await dataSource.query('DROP TABLE core."verifierActivityWrites"');
  }
  for (const offset of [0, 21_000, 42_000, 63_000, 84_000]) {
    clock(offset); await successful(service.resolveSession(active.sessionToken));
  }
  const stored = await repo.findOneByOrFail({ id: active.session.id });
  expect(stored.lastActiveAt.getTime()).toBeGreaterThanOrEqual(baseClock + 63_000);
  await successful(service.revokeSessionByToken(active.sessionToken, 'USER_SIGN_OUT' as any));
  clock(105_000); await expectInvalid(active.sessionToken);
  clock(0); const idle = await successful(createSession(input())); await successful(service.resolveSession(idle.sessionToken));
