});

test('C05 scoped revocation and healthy cache invalidation', async () => {
  const [keep, removeA, removeB, foreign] = await Promise.all([createSession(input()), createSession(input()), createSession(input()), createSession(input({ userId: otherUser, userWorkspaceId: otherMembership }))]);
  for (const s of [keep, removeA, removeB, foreign]) await successful(service.resolveSession(s.sessionToken));
  expect(await rejected(service.revokeSessionByIdForUser({ sessionId: foreign.session.id, userId: uid, reason: 'USER_SIGN_OUT' as any }))).toBeDefined();
  expect(await service.revokeAllSessionsForUser({ userId: uid, reason: 'USER_SIGN_OUT' as any, exceptSessionId: keep.session.id })).toBe(2);
  await expectInvalid(removeA.sessionToken); await expectInvalid(removeB.sessionToken);
  await successful(service.resolveSession(keep.sessionToken)); await successful(service.resolveSession(foreign.sessionToken));
  expect(await service.revokeSessionByIdForUser({ sessionId: keep.session.id, userId: uid, reason: 'USER_SIGN_OUT' as any })).toBe(true);
  expect(await successful(service.revokeSessionByToken(keep.sessionToken, 'USER_SIGN_OUT' as any))).toBe(false);
  await expectInvalid(keep.sessionToken);
