test('C06 deterministic revoke versus Redis fill races', async () => {
  for (const touching of [false, true]) {
    clock(0); const created = await successful(createSession(input()));
    if (touching) { await successful(service.resolveSession(created.sessionToken)); clock(301_000); }
    let reach!: () => void, release!: () => void;
    const reached = new Promise<void>(r => reach = r), gate = new Promise<void>(r => release = r);
    // Pause the resolution's first cache write, whichever CacheStorageService write method the submission
    // uses for its read-through fill (set, setIfAbsent or mset), and never pause the revocation itself.
    let paused = false, armed = true;
    const spies = ['set', 'setIfAbsent', 'mset'].filter((m) => typeof (cache as any)[m] === 'function').map((m) => {
      const original = (cache as any)[m].bind(cache);
      return jest.spyOn(cache as any, m as any).mockImplementation(async (...args: any[]) => {
        if (armed && !paused) { paused = true; reach(); await gate; }
        return original(...args);
      });
    });
    const resolution = service.resolveSession(created.sessionToken).then(() => 'accepted', () => 'rejected');
    await Promise.race([reached, resolution]); armed = false;
    await successful(service.revokeSessionByToken(created.sessionToken, 'USER_SIGN_OUT' as any));
    release(); await resolution; spies.forEach((s: any) => s.mockRestore());
    await expectInvalid(created.sessionToken);
  }
});

test('C07 refresh revocation survives session failure and verifies JWT', async () => {
  const id = uuid(), untouchedId = uuid();
  await appTokens.save([{ id, type: AppTokenType.RefreshToken }, { id: untouchedId, type: AppTokenType.RefreshToken }]);
  const payload = { type: 'REFRESH', userId: uid, sub: uid, jti: id };
  const token = jwt.sign(payload, wrapper.generateAppSecret('REFRESH' as any, uid), { expiresIn: '1h' });
  const spy = jest.spyOn(service, 'revokeSessionByToken').mockRejectedValueOnce(new Error('injected storage outage'));
  expect(await rejected(service.signOut({ sessionToken: 'sess_missing', refreshToken: token }))).toMatchObject({message:'injected storage outage'});
  spy.mockRestore();
  expect((await appTokens.findOneByOrFail({ id })).revokedAt).not.toBeNull();
  const forged = jwt.sign({ ...payload, jti: untouchedId }, 'incorrect-secret');
  await successful(service.signOut({ refreshToken: forged }));
  expect((await appTokens.findOneByOrFail({ id: untouchedId })).revokedAt).toBeNull();
});

test('C08 real HTTP CSRF request-origin matrix', async () => {
  const s = await successful(createSession(input()));
  const app = express(), csrf = new CookieSessionCsrfMiddleware(config, cookies, wrapper);
  app.use((req, res, next) => csrf.use(req, res, next)); app.use((_req, res) => { res.json({ reached: true }); });
  const scenarios = [
    { method: 'post', cookie: true, origin: 'http://crm.example.test', status: 200 },
    { method: 'post', cookie: true, origin: 'http://crm.example.test:80', status: 200 },
    { method: 'post', cookie: true, origin: 'http://evil.example.test', status: 403 },
    { method: 'post', cookie: true, status: 403 },
    { method: 'post', cookie: true, origin: 'null', status: 403 },
    { method: 'post', cookie: true, origin: 'not-a-url', status: 403 },
    { method: 'get', cookie: true, origin: 'http://evil.example.test', status: 200 },
    { method: 'head', cookie: true, origin: 'http://evil.example.test', status: 200 },
    { method: 'options', cookie: true, status: 200 },
    { method: 'post', cookie: false, origin: 'http://evil.example.test', status: 200 },
    { method: 'post', cookie: true, authorization: 'Bearer an-api-token', status: 200 },
    { method: 'post', cookie: true, authorization: 'Basic not-a-bearer', status: 403 },
  ];
  for (const c of scenarios) {
    let q = (request(app) as any)[c.method]('/mutation').set('Host', 'crm.example.test');
    if (c.cookie) q = q.set('Cookie', `twenty-session=${s.sessionToken}`);
